package fixture

func Total(nums []int) int {
	total := 0
	for _, n := range nums {
		total += n
	}
	return total
}

files.stats.go:
package fixture

func Average(nums []int) float64 {
	return float64(Total(nums)) / float64(len(nums))
}

files.stats_test.go:
package fixture

import "testing"

func TestAverage(t *testing.T) {
	if got := Average([]int{2, 4}); got != 3 {
		t.Fatalf("Average = %v, want 3", got)
	}
	if got := Average(nil); got != 0 {
		t.Fatalf("Average(nil) = %v, want 0", got)
	}
}
